+          chalk.dim(`\n      Every registration launches \`ix mcp\` and will fail until it resolves.`),
+  );
+  console.log(chalk.dim(`  ${report.toolCount} tools advertised`));
+  console.log();
+  for (const host of report.hosts) console.log(renderHostLine(host));
